let
  cfg = config.dotenv;

  normalizeFilenames = filenames: if lib.isList filenames then filenames else [ filenames ];
  cliOwnedNames = [ "SHELL" "DEVENV_CMDLINE" ];
  dotenvEnvModuleLocation = "devenv:dotenv-resolved";
  dotenvEnvModule =
    { config
    , devenvPrimops ? { }
    , lib
