    {
      _file = dotenvEnvModuleLocation;
      config = lib.mkIf config.dotenv.enable {
        dotenv.resolved = builtins.removeAttrs
          (loadDotenv (normalizeFilenames config.dotenv.filename) config.dotenv.substitution)
