+//! External supervision lifecycle integration tests.
+
+mod common;
+
+use common::*;
+use devenv_processes::{
+    HttpGetProbe, HttpProbe, OnIdle, ProcessConfig, ProcessPhase, ReadyConfig, RestartConfig,
