+        return false;
+    }
+    if model.get_activity(activity_id).is_some_and(|activity| {
+        matches!(activity.variant, crate::model::ActivityVariant::Process(_))
+    }) {
+        ui_state.hide_process_previews();
+    } else {
+        ui_state.inline_logs_activity = None;
+    }
