+fn resolved_scroll_offset(
+    scroll_offset: usize,
+    follow_tail: bool,
+    scroll_anchor: Option<ScrollAnchor>,
+    buffer_start_line: usize,
+    visual_rows: &[VisualRow],
+    total_visual_rows: usize,
