+        .enumerate()
+        .flat_map(|(log_idx, line)| {
+            case_insensitive_match_ranges(line, query).into_iter().map(
+                move |(char_start, char_end)| LogSearchMatch {
+                    log_line: buffer_start_line + log_idx,
+                    char_start,
+                    char_end,
+                },
+            )
+        })
