+    visible_cursor
+        .and_then(|cursor| {
+            matches.iter().find(|search_match| {
+                let candidate = search_cursor(**search_match);
+                (candidate.log_line, candidate.char_start) >= (cursor.log_line, cursor.char_start)
+            })
