+                        .with_terminal_width(terminal_size.width)
+                        .with_border_indent(display.depth * 2)
+                        .visual_height()
+                })
+        })
+        .sum();
+    let available_rows = terminal_size.height.saturating_sub(SUMMARY_BAR_HEIGHT) as usize;
