+fn disclosed_name(activity: &Activity, disclosure: Option<&ActivityDisclosure>) -> String {
+    match disclosure {
+        Some(disclosure) if disclosure.collapsed => format!("▸ {}", activity.name),
+        Some(_) => format!("▾ {}", activity.name),
+        None => activity.name.clone(),
+    }
