+                    current_scroll_offset,
+                    buffer_start_line,
+                    visual_rows,
+                );
+                search.current = chosen.map(search_cursor);
+                if let Some(chosen) = chosen {
+                    focus_search_match(
+                        chosen,
+                        viewport_height,
+                        max_offset,
+                        scroll_offset,
+                        follow_tail,
+                        scroll_anchor,
+                        buffer_start_line,
+                        visual_rows,
+                    );
+                }
+                log_search.set(Some(search));
+            }
+            KeyCode::Char(character) if !control && !alt => {
+                search.query.push(character);
+                let matches = find_log_matches(logs, buffer_start_line, &search.query);
+                let chosen = choose_search_match(
+                    &matches,
+                    search.current,
+                    current_scroll_offset,
+                    buffer_start_line,
+                    visual_rows,
+                );
+                search.current = chosen.map(search_cursor);
+                if let Some(chosen) = chosen {
+                    focus_search_match(
+                        chosen,
+                        viewport_height,
+                        max_offset,
+                        scroll_offset,
+                        follow_tail,
+                        scroll_anchor,
+                        buffer_start_line,
+                        visual_rows,
+                    );
+                }
+                log_search.set(Some(search));
+            }
+            _ => {}
+        }
+        return true;
+    }
+
+    if matches!(key_event.code, KeyCode::Char('/')) && !control && !alt {
+        log_search.set(Some(LogSearchState {
+            query: String::new(),
+            current: None,
+            editing: true,
+            origin: LogSearchOrigin {
+                offset: current_scroll_offset,
+                scroll_mode: ScrollMode {
+                    follow_tail: follow_tail.get(),
+                    anchor: scroll_anchor.get(),
+                },
+            },
+        }));
+        return true;
+    }
+
+    let Some(mut search) = current_search else {
+        return false;
+    };
+
+    match key_event.code {
+        KeyCode::Esc => {
+            log_search.set(None);
+            true
+        }
+        KeyCode::Char('n') | KeyCode::Char('N') if !control && !alt => {
+            let matches = find_log_matches(logs, buffer_start_line, &search.query);
+            let chosen = adjacent_search_match(
+                &matches,
+                search.current,
+                matches!(key_event.code, KeyCode::Char('n')),
+            );
+            search.current = chosen.map(search_cursor);
+            if let Some(chosen) = chosen {
+                focus_search_match(
+                    chosen,
+                    viewport_height,
+                    max_offset,
+                    scroll_offset,
+                    follow_tail,
+                    scroll_anchor,
+                    buffer_start_line,
+                    visual_rows,
+                );
+            }
+            log_search.set(Some(search));
+            true
+        }
+        _ => false,
+    }
+}
